fn frame(t: i32) {
    let w: i32 = host::display::width();
    let tx: i32 = 40;
    let tw: i32 = w - 80;
    let ty: i32 = 140;
    let down: i32 = host::display::pointer_down();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut v: i32 = host::display::state_get(0);
    if down == 1 && py >= ty - 20 && py < ty + 24 {
        let mut raw: i32 = (px - tx) * 100 / tw;
        if raw < 0 { raw = 0; }
        if raw > 100 { raw = 100; }
        v = (raw + 12) / 25 * 25;
        if v > 100 { v = 100; }
        host::display::state_set(0, v);
    }
    host::display::clear(0x101010);
    host::display::fill_rect(tx, ty, tw, 4, 0x404040);
    let mut i: i32 = 0;
    while i < 5 {
        let tkx: i32 = tx + i * 25 * tw / 100;
        host::display::fill_rect(tkx - 1, ty - 8, 2, 20, 0x606060);
        i = i + 1;
    }
    let hx: i32 = tx + v * tw / 100;
    host::display::fill_rect(hx - 7, ty - 12, 14, 28, 0x00ccff);
    host::display::draw_string(tx, 70, "SNAPPED", 0x808080, 1);
    host::display::draw_number(tx, 86, v, 0xffffff, 3);
    host::display::present();
}
